    CONSTRAINT assistant_conversation_account_check CHECK ((octet_length(account) <= 1024)),
    CONSTRAINT assistant_conversation_app_check CHECK ((octet_length(app) <= 128)),
    CONSTRAINT assistant_conversation_state_check CHECK ((state = ANY (ARRAY['idle'::text, 'awaiting'::text]))),
    CONSTRAINT assistant_conversation_tenant_check CHECK ((octet_length(tenant) <= 128)),
    CONSTRAINT assistant_conversation_title_check CHECK ((octet_length(title) <= 200))
);
CREATE TABLE mistri.assistant_event (
    conversation text NOT NULL COLLATE pg_catalog."C",
    seq integer NOT NULL,
    kind text NOT NULL,
    body_json text NOT NULL,
    at text NOT NULL,
    CONSTRAINT assistant_event_body_json_check CHECK (((octet_length(body_json) <= 524288) AND ((body_json)::json IS NOT NULL)))
);
