    CONSTRAINT assistant_memory_content_check CHECK ((octet_length(content) <= 1000)),
    CONSTRAINT assistant_memory_scope_check CHECK ((scope = ANY (ARRAY['person'::text, 'app'::text]))),
    CONSTRAINT assistant_memory_source_check CHECK ((source = ANY (ARRAY['assistant'::text, 'person'::text]))),
    CONSTRAINT assistant_memory_tenant_check CHECK ((octet_length(tenant) <= 128))
);
CREATE TABLE mistri.assistant_meta (
